/**
 * Known-answer (canary) tests for the feed-permission DAG-CBOR wire format.
 *
 * The expected hex and CID values below are generated by the Go implementation and
 * mirrored here, proving byte-identical DAG-CBOR output between TypeScript and Go.
 *
 * Must be kept in sync with
 * pulse-protocol-go/ipfs/cbor_feedpermission_known_test.go.
 */

import type { FeedPermissionPayload } from '@pulse-protocol/types';
import { describe, expect, it } from 'vitest';
import { marshalFeedPermission, unmarshalFeedPermission } from '../cbor-feedpermission.js';
import { getCid } from '../cid.js';

/** Renders bytes as lower-case hex, for comparison with the Go canary values. */
function toHex(bytes: Uint8Array): string {
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

/** Fixed 33-byte compressed-key stand-ins — mirror knownNotaryKey1/2 in Go. */
function knownNotaryKey1(): Uint8Array {
  const k = new Uint8Array(33);
  k[0] = 0x02;
  return k;
}
function knownNotaryKey2(): Uint8Array {
  const k = new Uint8Array(33);
  k[0] = 0x03;
  return k;
}

/**
 * v1-shaped feed permission: no dataDescription and a legacy
 * "pulse/feeds/{feedType}/" container path. Mirrors knownV1Payload() in Go.
 */
const knownV1Payload: FeedPermissionPayload = {
  consentNo: 42,
  walletId: 'wlt-canary-v1',
  grantorWebId: 'https://pod.example/alice/profile/card#me',
  counterpartyDid: 'did:web:feeds.example.com',
  feedType: 'open-banking',
  podContainerPath: 'pulse/feeds/open-banking/',
  permissions: ['read', 'write'],
  dataCategories: ['transaction-history', 'account-balance'],
  issuedAt: 1_700_000_000,
  expiresAt: 1_730_000_000,
  encryptedNotary: new Uint8Array([0x01, 0x02, 0x03, 0x04, 0x05]),
  notaryKey1: knownNotaryKey1(),
  notaryKey2: knownNotaryKey2(),
};

// Captured from the Go implementation as it stood before the v2 work (issue #519).
const knownV1Hex =
  '';
const knownV1Cid = 'bafyreic6ntajpiaijirww2ghopyqyzccffrjv3h5h6r4nsgljiza7rcuia';

const knownGrantorXpub = 'xpub661MyMwAqRbcGRandomTestXpubValue';

const knownV1XpubHex =
  '';
const knownV1XpubCid = 'bafyreiewgchrq32ixuofa3mhhd6qwid3tjbq2qhf2owed3x54vrghjo3xi';

/**
 * Generalised inbound-feed permission — a verified-credential provider granted
 * write access to "pulse/credentials/identity/", with a human-readable data
 * description. Both are v2-only features. Mirrors knownV2Payload() in Go.
 */
const knownV2Payload: FeedPermissionPayload = {
  consentNo: 7,
  walletId: 'wlt-canary-v2',
  grantorWebId: 'https://pod.example/alice/profile/card#me',
  counterpartyDid: 'did:web:vc.example.com',
  feedType: 'verified-identity',
  podContainerPath: 'pulse/credentials/identity/',
  permissions: ['write'],
  dataCategories: ['identity-document'],
  dataDescription: 'Verified Identity Credential',
  issuedAt: 1_700_000_000,
  expiresAt: 1_730_000_000,
  encryptedNotary: new Uint8Array([0x01, 0x02, 0x03, 0x04, 0x05]),
  notaryKey1: knownNotaryKey1(),
  notaryKey2: knownNotaryKey2(),
};

const knownV2Hex =
  '';
const knownV2Cid = 'bafyreic4owlz2uf5xezrdqz4puabncdtgardr32r5k7v5ndsmoti76knpu';

const knownV2XpubHex =
  '';
const knownV2XpubCid = 'bafyreic6zre32hvmfc7r66x25k7odgz4ceyoqx6uboayqitzqkmassstym';

/**
 * The v2 canary varied: the same verified-credential permission, now carrying a
 * previousCid pointing at the record it supersedes (the v1 canary). previousCid
 * is a v3-only feature and composes with the v2-only features already present.
 * Mirrors knownV3Payload() in Go.
 */
const knownV3Payload: FeedPermissionPayload = {
  ...knownV2Payload,
  previousCid: knownV1Cid,
};

const knownV3Hex =
  '';
const knownV3Cid = 'bafyreihmfpvga3o7mmryviquqppfuoe6tw75e22xywjgx7rr3njddnjtxq';

const knownV3XpubHex =
  '';
const knownV3XpubCid = 'bafyreif5vls5zhj57avbwcfgkxadpfgftozww7gk7l2jmfn27v5w4wx4wu';

describe('feed-permission v1 known answers', () => {
  it('marshals the v1 canary payload to the exact Go bytes', () => {
    expect(toHex(marshalFeedPermission(knownV1Payload))).toBe(knownV1Hex);
  });

  it('produces the CID recorded by the Go implementation', async () => {
    expect(await getCid(marshalFeedPermission(knownV1Payload))).toBe(knownV1Cid);
  });

  it('decodes the stored v1 canary bytes', () => {
    const block = Uint8Array.from(
      (knownV1Hex.match(/../g) ?? []).map((h) => Number.parseInt(h, 16)),
    );
    const got = unmarshalFeedPermission(block);
    expect(got.consentNo).toBe(knownV1Payload.consentNo);
    expect(got.podContainerPath).toBe(knownV1Payload.podContainerPath);
    expect(got.permissions).toEqual(knownV1Payload.permissions);
    expect(got.dataCategories).toEqual(knownV1Payload.dataCategories);
    expect(got.encryptedNotary).toEqual(knownV1Payload.encryptedNotary);
  });

  it('marshals the v1 canary payload with grantorXpub to the exact Go bytes', async () => {
    const block = marshalFeedPermission({ ...knownV1Payload, grantorXpub: knownGrantorXpub });
    expect(toHex(block)).toBe(knownV1XpubHex);
    expect(await getCid(block)).toBe(knownV1XpubCid);
  });
});

describe('feed-permission v2 known answers', () => {
  it('marshals the v2 canary payload to the exact Go bytes', async () => {
    const block = marshalFeedPermission(knownV2Payload);
    expect(toHex(block)).toBe(knownV2Hex);
    expect(await getCid(block)).toBe(knownV2Cid);
  });

  it('marshals the v2 canary payload with grantorXpub to the exact Go bytes', async () => {
    const block = marshalFeedPermission({ ...knownV2Payload, grantorXpub: knownGrantorXpub });
    expect(toHex(block)).toBe(knownV2XpubHex);
    expect(await getCid(block)).toBe(knownV2XpubCid);
  });

  it('decodes the pinned v2 bytes', () => {
    const block = Uint8Array.from(
      (knownV2Hex.match(/../g) ?? []).map((h) => Number.parseInt(h, 16)),
    );
    const got = unmarshalFeedPermission(block);
    expect(got.podContainerPath).toBe(knownV2Payload.podContainerPath);
    expect(got.dataDescription).toBe(knownV2Payload.dataDescription);
    expect(got.feedType).toBe(knownV2Payload.feedType);
    expect(got.permissions).toEqual(knownV2Payload.permissions);
    expect(got.grantorXpub).toBeUndefined();
  });
});

describe('feed-permission v3 known answers', () => {
  it('marshals the v3 canary payload to the exact Go bytes', async () => {
    const block = marshalFeedPermission(knownV3Payload);
    expect(toHex(block)).toBe(knownV3Hex);
    expect(await getCid(block)).toBe(knownV3Cid);
  });

  it('marshals the v3 canary payload with grantorXpub to the exact Go bytes', async () => {
    const block = marshalFeedPermission({ ...knownV3Payload, grantorXpub: knownGrantorXpub });
    expect(toHex(block)).toBe(knownV3XpubHex);
    expect(await getCid(block)).toBe(knownV3XpubCid);
  });

  it('decodes the pinned v3 bytes', () => {
    const block = Uint8Array.from(
      (knownV3Hex.match(/../g) ?? []).map((h) => Number.parseInt(h, 16)),
    );
    const got = unmarshalFeedPermission(block);
    expect(got.previousCid).toBe(knownV3Payload.previousCid);
    expect(got.dataDescription).toBe(knownV3Payload.dataDescription);
    expect(got.grantorXpub).toBeUndefined();
  });

  it('leaves the v1 and v2 canary bytes untouched now the optional field exists', async () => {
    const v1 = marshalFeedPermission(knownV1Payload);
    expect(toHex(v1)).toBe(knownV1Hex);
    expect(await getCid(v1)).toBe(knownV1Cid);

    const v2 = marshalFeedPermission(knownV2Payload);
    expect(toHex(v2)).toBe(knownV2Hex);
    expect(await getCid(v2)).toBe(knownV2Cid);
  });
});
